"""Figures for reports/LATE_SALE_TRIGGER.md -> outputs/trig2/trigger_events.png, trigger_state.png. Markers carry the meaning (shape = side; filled = matched by the frozen futures ladder)."""
import os, json, numpy as np, pandas as pd, matplotlib; matplotlib.use('Agg'); import matplotlib.pyplot as plt
T2 = os.path.join(os.path.dirname(os.path.abspath(__file__)), '..', 'outputs', 'trig2'); SURF, INK, INK2, GRID = '#fcfcfb', '#0b0b0b', '#52514e', '#e4e3df'; BLUE, ORANGE, AQUA = '#2a78d6', '#eb6834', '#1baf7a'
plt.rcParams.update({'figure.facecolor': SURF, 'axes.facecolor': SURF, 'savefig.facecolor': SURF, 'axes.edgecolor': GRID, 'axes.labelcolor': INK2, 'xtick.color': INK2, 'ytick.color': INK2, 'text.color': INK, 'font.size': 8.5, 'axes.titlesize': 9.5, 'axes.titleweight': 'bold', 'axes.titlelocation': 'left', 'axes.spines.top': False, 'axes.spines.right': False, 'grid.color': GRID, 'axes.grid': True, 'axes.axisbelow': True})
E = pd.read_csv(f'{T2}/events.csv'); M = pd.read_csv(f'{T2}/clock_minutes.csv'); H = pd.read_csv(f'{T2}/state_hazard.csv'); inc = json.load(open(f'{T2}/incremental.json'))
short = lambda c: c.replace('NIFTY|2026-', 'NIF ').replace('SENSEX|2026-', 'SEN ')
cyc = sorted(set(E.cyc), key=lambda c: (c.split('|')[1])); yi = {c: i for i, c in enumerate(cyc)}; xs = lambda t: (t - 54900) / 60 + 15 * 60 + 15
fig, ax = plt.subplots(2, 1, figsize=(12, 8.6), gridspec_kw=dict(height_ratios=[3.2, 1.5]), sharex=True); a = ax[0]
for t_, lab in ((15 * 60 + 15, '15:15 index freezes'), (15 * 60 + 20, '15:20 indicative values start'), (15 * 60 + 29, '15:29 official close'), (15 * 60 + 30, '15:30 candle end')): a.axvline(t_, color=INK2, lw=0.8, ls=':'); a.text(t_ + 0.1, len(cyc) - 0.25, lab, rotation=90, va='top', fontsize=7.5, color=INK2)
for r in E.itertuples():
    x = xs(r.t0); y = yi[r.cyc]; lad = 'LADDER' in str(r.labels); size = 20 + 14 * min(r.n, 8)
    if r.type == 'pair': a.scatter(x, y, marker='D', s=size, facecolor=INK if lad else SURF, edgecolor=INK, lw=1.2, zorder=3)
    else:
        cp = r.ce_lots > 0; a.scatter(x, y, marker='v' if cp else '^', s=size, facecolor=(BLUE if cp else ORANGE) if lad else SURF, edgecolor=BLUE if cp else ORANGE, lw=1.3, zorder=3)
a.set_yticks(range(len(cyc))); a.set_yticklabels([short(c) for c in cyc], fontsize=8); a.set_ylim(-0.7, len(cyc) - 0.2); a.grid(axis='x'); a.grid(axis='y', alpha=0.4)
a.set_title('Late D-1 sale bursts by cycle: ▼ call, ▲ put, ◆ both legs within 10 s (filled = matched by the frozen futures ladder; size = orders in the burst)')
b = ax[1]; g = M.groupby('j').agg(ev=('y', 'sum'), feed=('d_feed', 'median'), fut=('d_fut', 'median')); xm = (g.index - 360) + 15 * 60 + 15; b.bar(xm, g.ev, width=0.8, color=GRID, edgecolor=INK2, lw=0.6, label='bursts starting in the minute (all cycles)'); b.set_ylabel('bursts'); b2 = b.twinx(); b2.plot(xm, g.feed, color=ORANGE, lw=1.8, label='median |Δ published index| (÷ pre-15:15 normal)'); b2.plot(xm, g.fut, color=BLUE, lw=1.8, label='median |Δ futures|'); b2.set_ylabel('minute move, ÷ normal'); b2.spines['right'].set_visible(True); b2.grid(False)
h1, l1 = b.get_legend_handles_labels(); h2, l2 = b2.get_legend_handles_labels(); b.legend(h1 + h2, l1 + l2, frameon=False, fontsize=7.8, loc='upper right')
b.set_xticks([15 * 60 + 15 + k for k in range(0, 26, 5)]); b.set_xticklabels([f'15:{15 + k:02d}' for k in range(0, 26, 5)]); b.set_xlim(15 * 60 + 14, 15 * 60 + 40); b.set_title('Bursts pile into a few minutes; the published index jumps at 15:20–15:23 but the side follows the futures')
fig.tight_layout(); fig.savefig(f'{T2}/trigger_events.png', dpi=150); plt.close(fig)
fig, ax = plt.subplots(1, 2, figsize=(12.5, 4.6), gridspec_kw=dict(width_ratios=[1.35, 1])); a = ax[0]; Hs = H.sort_values('auc'); y = np.arange(len(Hs))
lab = {'sold_deficit': 'sold-lot deficit (other − same side)', 'net_deficit': 'net-lot deficit (after stops)', 'cover_same_5': 'same-side covers, last 5 min', 'cover_other_5': 'other-side covers, last 5 min', 'mtm_pnl': 'book MTM P&L', 'mtm_change_15': 'book MTM change, 15 min', 'decay_same': 'decay of held same-side shorts', 'peak_deficit_same': 'shortfall vs same-side peak', 'mins_since_sale': 'minutes since last sale', 'mins_since_cover': 'minutes since last cover', 'straddle_chg_15': 'ATM straddle change, 15 min', 'straddle_vs_0920': 'ATM straddle vs 09:20'}
a.hlines(y, Hs.null_mean, Hs.auc, color=GRID, lw=2); a.scatter(Hs.null_mean, y, marker='|', s=90, color=INK2, label='curveball-null mean'); a.scatter(Hs.auc, y, s=46, color=[AQUA if (p <= 0.10) else SURF for p in Hs.p_bh], edgecolor=INK, lw=1.0, zorder=3, label='observed (filled = BH ≤ 10% within these 12)'); a.axvline(0.5, color=INK2, lw=0.8); a.set_yticks(y); a.set_yticklabels([lab[f] for f in Hs.feature]); a.set_xlabel('stratified hazard AUC (below 0.5 = sale when the feature is LOW)'); a.set_title('Portfolio-state features: 12 tested'); a.legend(frameon=False, fontsize=8, loc='lower right'); a.grid(axis='x')
b = ax[1]; nm = ['clock\nonly', 'frozen\nfeatures\n(strictly before)', '+ sold-lot\ndeficit', '+ straddle\nchange', 'state only\n+ clock']; keys = ['base', 'A_frozen_features_strictly_before', 'B_A_plus_sold_deficit', 'C_A_plus_straddle_chg_15', 'E_state_only_plus_clock']; v = [inc['aucs'][k] for k in keys]
b.bar(range(5), v, color=[GRID, GRID, GRID, BLUE, BLUE], edgecolor=INK2, lw=0.7, width=0.7); b.axhline(0.5, color=INK2, lw=0.8); b.set_ylim(0.45, 0.8); b.set_xticks(range(5)); b.set_xticklabels(nm, fontsize=7.8)
for i_, x_ in enumerate(v): b.text(i_, x_ + 0.006, f'{x_:.3f}', ha='center', fontsize=8.5)
b.set_ylabel('leave-one-cycle-out stratified AUC'); b.set_title(f"Straddle change adds +{inc['C_vs_A']['delta']:.3f} to the frozen features\n95% CI {np.round(inc['C_vs_A']['boot95'], 3).tolist()}", fontsize=9.5); b.grid(axis='x', visible=False)
fig.tight_layout(); fig.savefig(f'{T2}/trigger_state.png', dpi=150); plt.close(fig); print('ok')
